{"command": "cd /workspace && python3 - <<'EOF'
import build
LBL={v:k for k,v in build.CH.items()}
def dump(pat, rows=None, chans=None):
    rows = rows or list(range(64))
    grid={}
    for x in build.calls:
        a=x['arguments']
        if a['pattern']!=pat: continue
        grid.setdefault((a['row'],a['channel']), []).append(a)
    chans = chans or sorted(LBL)
    print('pattern',pat)
    print('row  ' + ' '.join('%-9s'%LBL[c] for c in chans))
    for r in rows:
        line=[]
        for c in chans:
            cells=grid.get((r,c),[])
            s=''
            for a in cells:
                n=a.get('note','...')
                s+= '%s'%n
            line.append('%-9s'%s)
        print('%3d  '%r + ' '.join(line))
dump(2, rows=list(range(0,20)) + list(range(44,64)))
EOF"}
